tests:
def test_basic():
    assert parse_decimal('3.14') == 3.14
def test_spaces():
    assert parse_decimal('  42  ') == 42.0
def test_commas():
    assert parse_decimal('1,234.5') == 1234.5
def test_invalid():
    assert parse_decimal('abc') is None
    assert parse_decimal('') is None
    assert parse_decimal(None) is None

def test_flat():
    assert flatten_once([1, 2]) == [1, 2]
def test_one_level():
    assert flatten_once([[1, 2], [3], 4]) == [1, 2, 3, 4]
def test_not_recursive():
    assert flatten_once([[1, [2]], 3]) == [1, [2], 3]
def test_tuples_kept():
    assert flatten_once([(1, 2), 'ab']) == [(1, 2), 'ab']

def test_odd():
    assert median([3, 1, 2]) == 2
def test_even():
    assert median([4, 1, 3, 2]) == 2.5
def test_empty():
    try:
        median([])
        assert False, 'must raise'
    except ValueError:
        pass

def test_simple():
    assert roman_to_int('III') == 3
def test_subtractive():
    assert roman_to_int('IX') == 9
    assert roman_to_int('XIV') == 14
def test_large():
    assert roman_to_int('MCMXCIV') == 1994
def test_lower():
    assert roman_to_int('xlvii') == 47

def test_basic():
    assert group_by_parity([1, 2, 3, 4]) == {'even': [2, 4], 'odd': [1, 3]}
def test_negative():
    assert group_by_parity([-3, -2]) == {'even': [-2], 'odd': [-3]}
def test_empty():
    assert group_by_parity([]) == {'even': [], 'odd': []}

def test_short():
    assert truncate_middle('abc', 5) == 'abc'
def test_long():
    r = truncate_middle('abcdefghij', 7)
    assert len(r) == 7 and '\u2026' in r
def test_exact():
    r = truncate_middle('abcdef', 3)
    assert len(r) <= 3

def test_found():
    assert deep_get({'a': {'b': 1}}, 'a.b') == 1
def test_missing():
    assert deep_get({'a': {}}, 'a.b', 'X') == 'X'
def test_nondict_midway():
    assert deep_get({'a': 5}, 'a.b', 'X') == 'X'
def test_default_none():
    assert deep_get({}, 'x') is None

def test_ok():
    assert is_balanced('(a[b]{c})') is True
def test_wrong_close():
    assert is_balanced('([)]') is False
def test_unclosed():
    assert is_balanced('(') is False
def test_none():
    assert is_balanced('no brackets') is True
